def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def expand_cfg(cfg, w):
    st, pb, A, g0, s, items, G = cfg
    return (st, pb, A, g0, s, expand(items, w), G)





def waypoints_rle(j, b):
    """The full asserted waypoint chain TOP15 -> ... -> TOP16
    (plus the r16' = 2 / 4 / 6 and band closing waypoints), in
    run-length form.  Kept unexpanded -- at this phase's scale
    one expanded chain is ~1.6 TB of tuples."""
    j16 = j - 271970481
    tail = (('P', 1, 1), ('R', b - 1))
    pts = []
    pts.append(('C', TOP15F, 147491795, 271970478, 2,
                (('P', 2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP15F, 147491794, 1, 271970478,
                (('P', 2, 2), ('P', 2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F16, 271970478, 1, 2,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F16, 271970478, 1, 4,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F16, 271970478, 3, 2,
                (('P', 2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F16, 0, 3, 2, (('R', 271970478), 'W'), 1))
    pts.extend(CASCADE62_WPS)
    # TOP16 state reached; closing waypoints by r16' = 2 * j16.
    if j16 == 1:
        pts.append(('B', (S16 + 1,) + TOP16F, SH16 + 1, 1, 3,
                    (('R', b - 1),), 1))
    if j16 == 2:
        pts.append(('C', TOP16F, S16, SH16 - 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP16F, S16 - 1, 1, SH16 - 1,
                    (('P', 2, 2), ('P', 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', (SH16, S16) + TOP16F, 3, 1, 3,
                    (('R', b - 1),), 1))
    if j16 == 3:
        pts.append(('C', TOP16F, S16, SH16 - 1, 2,
                    (('P', 4, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP16F, S16 - 1, 1, SH16 - 1,
                    (('P', 2, 2), ('P', 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F17, SH16 - 1, 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', F17, SH16 - 1, 1, 4,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', (SH16, S16) + TOP16F, 5, 1, 3,
                    (('R', b - 1),), 1))
    if j16 >= 4:
        pts.append(('C', TOP16F, S16, SH16 - 1, 2,
                    (('P', 2 * j16 - 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', TOP16F, S16 - 1, 1, SH16 - 1,
                    (('P', 2, 2), ('P', 2 * j16 - 2, 2),
                     ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('C', F17, SH16 - 1, 1, 2,
                    (('P', 2 * j16 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F17, SH16 - 1, 1, 4,
                    (('P', 2 * j16 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F17, SH16 - 1, 3, 2,
                    (('P', 2 * j16 - 6, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F17, SH16 - 1, 1, 2 * j16 - 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
    return pts


def check_chain(j, b, cap=120000000):
    """check_chain with lazy waypoint expansion (the Phase 56
    scale forbids materialising the whole chain).  Matching,
    skip recording and lemmastep replay verification are
    hsim55's, verbatim in behaviour."""
    rle = waypoints_rle(j, b)
    w = W(2 * (j - 271970481), b)
    N = len(rle)
    cache = {}

    def target(k):
        if k not in cache:
            if len(cache) > 24:
                cache.clear()
            cache[k] = norm(expand_cfg(rle[k], w))
        return cache[k]

    pos = -1
    status = fin = None
    used = set()
    src = TOP15(j, b)
    anchor = norm(src)
    skips = []  # (anchor, [skipped waypoints], landing)
    for rec in swalk(src, max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        if pos + 1 < N:
            if _matches(rec, target(pos + 1)):
                pos += 1
                anchor = target(pos)
            else:
                for k in range(pos + 2, min(pos + 9, N)):
                    if _matches(rec, target(k)):
                        skips.append((anchor,
                                      [target(t)
                                       for t in range(pos + 1, k)],
                                      target(k)))
                        pos = k
                        anchor = target(pos)
                        break
    assert pos == N - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(target(pos + 1)))
    for (anchor, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = anchor
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('verify replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'j=%d b=%d: skipped waypoint not verified: %s' \
            % (j, b, fmt(targets[ti]))
    return status, fin, pos, used



def front_check(j, b):
    """The front segment TOP15(j, b) -> DIP14 spine (waypoints
    0..5), with check_chain's skip recording + lemmastep
    replay verification and early exit at the spine."""
    rle = waypoints_rle(j, b)
    w = W(2 * (j - 271970481), b)
    pts = [norm(expand_cfg(c, w)) for c in rle[:6]]
    pos = -1
    anchor = norm(TOP15(j, b))
    skips = []
    for rec in swalk(TOP15(j, b), max_steps=20000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if pos + 1 < len(pts):
            if _matches(rec, pts[pos + 1]):
                pos += 1
                anchor = pts[pos]
            else:
                for k in range(pos + 2, min(pos + 9, len(pts))):
                    if _matches(rec, pts[k]):
                        skips.append((anchor, pts[pos + 1:k],
                                      pts[k]))
                        pos = k
                        anchor = pts[pos]
                        break
        if pos == len(pts) - 1:
            break
    assert pos == len(pts) - 1, \
        'front j=%d b=%d: waypoint %d missing' % (j, b, pos + 1)
    for (a0, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = a0
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('front replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'front j=%d b=%d: skipped waypoint not verified' \
            % (j, b)



def TOP16(j16, b):
    return ('B', TOP16F, S16, 1, SH16,
            ((2 * j16, 2), (1, 1)) + tuple(SP(b - 1)), 1)



